-- hqc hub, iteration 1 schema (SPEC §3). Ids are uuid v7 generated by the hub.
-- `state` and `queue_len` of a session are computed, not stored (SPEC §17.1).

CREATE TABLE users (
    id                  uuid PRIMARY KEY,
    email               text NOT NULL UNIQUE,
    display_name        text NOT NULL,
    timezone            text NOT NULL DEFAULT 'UTC',
    personal_project_id uuid,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE projects (
    id                   uuid PRIMARY KEY,
    owner_id             uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    name                 text NOT NULL,
    slug                 text NOT NULL,
    description          text NOT NULL DEFAULT '',
    default_workspace_id uuid,
    is_personal          boolean NOT NULL DEFAULT false,
    created_at           timestamptz NOT NULL DEFAULT now(),
    updated_at           timestamptz NOT NULL DEFAULT now(),
    UNIQUE (owner_id, slug)
);
CREATE UNIQUE INDEX projects_one_personal ON projects (owner_id) WHERE is_personal;

ALTER TABLE users
    ADD CONSTRAINT users_personal_project_fk
    FOREIGN KEY (personal_project_id) REFERENCES projects (id) ON DELETE SET NULL;

-- Fields copied from `hello` are for display only: the worker's local config is the
-- source of truth (SPEC §3 Worker, §14). Online status lives in the hub's memory.
CREATE TABLE workers (
    id                     uuid PRIMARY KEY,
    owner_id               uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    name                   text NOT NULL,
    os                     text NOT NULL DEFAULT '',
    -- sha256 of the bearer token, hex; null until the worker claims its token, and after revocation.
    token_hash             text UNIQUE,
    revoked_at             timestamptz,
    last_seen              timestamptz,
    protocol_version       integer,
    capabilities           jsonb NOT NULL DEFAULT '{}',
    environments           jsonb NOT NULL DEFAULT '[]',
    env_bindings           jsonb NOT NULL DEFAULT '[]',
    allowed_roots          jsonb NOT NULL DEFAULT '[]',
    allow_foreign_sessions boolean NOT NULL DEFAULT false,
    share_local_models     boolean NOT NULL DEFAULT false,
    local_models           jsonb NOT NULL DEFAULT '[]',
    created_at             timestamptz NOT NULL DEFAULT now(),
    updated_at             timestamptz NOT NULL DEFAULT now()
);

-- Enrollment codes (SPEC §5.1): TTL 10 minutes, confirmed by a logged-in user.
CREATE TABLE enroll_codes (
    id              uuid PRIMARY KEY,
    code            text NOT NULL UNIQUE,
    poll_token_hash text NOT NULL UNIQUE,
    name            text NOT NULL,
    os              text NOT NULL DEFAULT '',
    expires_at      timestamptz NOT NULL,
    confirmed_by    uuid REFERENCES users (id) ON DELETE CASCADE,
    confirmed_at    timestamptz,
    worker_id       uuid REFERENCES workers (id) ON DELETE CASCADE,
    created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE workspaces (
    id             uuid PRIMARY KEY,
    project_id     uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    owner_id       uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    worker_id      uuid NOT NULL REFERENCES workers (id) ON DELETE CASCADE,
    path           text NOT NULL,
    label          text NOT NULL DEFAULT '',
    environment    text NOT NULL DEFAULT 'default',
    ephemeral      boolean NOT NULL DEFAULT false,
    created_by_hqc boolean NOT NULL DEFAULT false,
    kind           text NOT NULL DEFAULT 'dir',
    mirror_enabled boolean NOT NULL DEFAULT false,
    created_at     timestamptz NOT NULL DEFAULT now(),
    updated_at     timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, worker_id, path)
);

CREATE TABLE sessions (
    id                 uuid PRIMARY KEY,
    project_id         uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    owner_id           uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    workspace_id       uuid REFERENCES workspaces (id) ON DELETE SET NULL,
    worker_id          uuid REFERENCES workers (id) ON DELETE SET NULL,
    cwd                text NOT NULL DEFAULT '.',
    title              text NOT NULL,
    slug               text NOT NULL,
    auto_approve       boolean NOT NULL DEFAULT false,
    wake_on_send       boolean NOT NULL DEFAULT false,
    locked_by          text NOT NULL DEFAULT 'none',
    last_seq           bigint NOT NULL DEFAULT 0,
    archived           boolean NOT NULL DEFAULT false,
    -- Agent (SPEC §3), embedded.
    runtime            text NOT NULL DEFAULT 'claude_code',
    acp_agent          text,
    model              text,
    runtime_session_id text,
    process_state      text NOT NULL DEFAULT 'stopped',
    system_prompt      text,
    disallowed_tools   jsonb NOT NULL DEFAULT '[]',
    restricted         boolean NOT NULL DEFAULT false,
    start_failures     integer NOT NULL DEFAULT 0,
    -- Hub bookkeeping for the computed state (SPEC §17.1): a delivered input started a turn
    -- that has not ended yet; the last turn ended with `status error`.
    turn_open          boolean NOT NULL DEFAULT false,
    last_turn_error    boolean NOT NULL DEFAULT false,
    -- sha256 of the session_token sent in the latest `session.start`.
    session_token_hash text,
    created_at         timestamptz NOT NULL DEFAULT now(),
    updated_at         timestamptz NOT NULL DEFAULT now(),
    UNIQUE (project_id, slug)
);
CREATE INDEX sessions_worker ON sessions (worker_id);

-- Events are append-only (SPEC §5.2). `payload` and `author` are stored as received;
-- only `delivery` / `delivered_at` change, and only on user.message / peer.message.
CREATE TABLE events (
    event_id     uuid PRIMARY KEY,
    session_id   uuid NOT NULL REFERENCES sessions (id) ON DELETE CASCADE,
    seq          bigint NOT NULL,
    ts           timestamptz NOT NULL,
    author       jsonb NOT NULL,
    type         text NOT NULL,
    payload      jsonb NOT NULL,
    chain        jsonb,
    client_op_id text,
    delivery     text,
    delivered_at timestamptz,
    created_at   timestamptz NOT NULL DEFAULT now(),
    UNIQUE (session_id, seq)
);
CREATE INDEX events_delivery ON events (session_id, seq) WHERE delivery IN ('pending', 'failed');
CREATE UNIQUE INDEX events_client_op ON events (session_id, client_op_id) WHERE client_op_id IS NOT NULL;

CREATE TABLE pending_requests (
    id                  uuid PRIMARY KEY,
    kind                text NOT NULL,
    session_id          uuid NOT NULL REFERENCES sessions (id) ON DELETE CASCADE,
    request_id          text NOT NULL,
    payload             jsonb NOT NULL,
    expires_at          timestamptz,
    from_session_id     uuid,
    from_event_id       uuid,
    worker_id           uuid REFERENCES workers (id) ON DELETE SET NULL,
    -- Frame `{type, payload}` for the worker once the request is answered or cancelled by the hub.
    result              jsonb,
    closed_at           timestamptz,
    result_delivered_at timestamptz,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    UNIQUE (session_id, kind, request_id)
);
CREATE INDEX pending_requests_open ON pending_requests (expires_at) WHERE closed_at IS NULL;

CREATE TABLE read_cursors (
    user_id       uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    session_id    uuid NOT NULL REFERENCES sessions (id) ON DELETE CASCADE,
    last_read_seq bigint NOT NULL DEFAULT 0,
    updated_at    timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, session_id)
);

CREATE TABLE push_subscriptions (
    id         uuid PRIMARY KEY,
    user_id    uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    endpoint   text NOT NULL UNIQUE,
    p256dh     text NOT NULL,
    auth       text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
